  "pycomputersdk/std.py": "\"\"\"\nSDK std module: re-exports app-level utilities from pycomputer.stdlib.appstdlib\n\"\"\"\n\nfrom pycomputer.stdlib.appstdlib import (\n    input, info, error, success, warning, confirm, pause,  # noqa: A004, re-export, not shadowing\n    section, subsection, banner, table, spinner, step,\n    clear, clear_line, hide_cursor, show_cursor,\n    bold, dim, green, red, yellow, cyan,\n    box, box_at,\n    print_exception, sleep, get_env, set_env, app_exit,\n    print_table, print_banner, ask_choice,\n    set_theme, get_theme,\n)\n\n__all__ = [\n    \"input\", \"info\", \"error\", \"success\", \"warning\", \"confirm\", \"pause\",\n    \"section\", \"subsection\", \"banner\", \"table\", \"spinner\", \"step\",\n    \"clear\", \"clear_line\", \"hide_cursor\", \"show_cursor\",\n    \"bold\", \"dim\", \"green\", \"red\", \"yellow\", \"cyan\",\n    \"box\", \"box_at\",\n    \"print_exception\", \"sleep\", \"get_env\", \"set_env\", \"app_exit\",\n    \"print_table\", \"print_banner\", \"ask_choice\",\n    \"set_theme\", \"get_theme\",\n]\n",
  "pycomputersdk/testing.py": "class MockRenderer:\n    def __init__(self):\n        self._buffer = []\n        self._cursor_x = 1\n        self._cursor_y = 1\n        self._output = []\n\n    def clear(self):\n        self._output = []\n        self._cursor_x = 1\n        self._cursor_y = 1\n        return self\n\n    def clear_line(self):\n        return self\n\n    def move(self, x, y):\n        self._cursor_x = x\n        self._cursor_y = y\n        return self\n\n    def write(self, text):\n        self._output.append(text)\n        return self\n\n    def flush(self):\n        return self\n\n    def hide_cursor(self):\n        return self\n\n    def show_cursor(self):\n        return self\n\n    def bold(self, text):\n        return text\n\n    def dim(self, text):\n        return text\n\n    def green(self, text):\n        return text\n\n    def bright_green(self, text):\n        return text\n\n    def red(self, text):\n        return text\n\n    def bright_red(self, text):\n        return text\n\n    def yellow(self, text):\n        return text\n\n    def cyan(self, text):\n        return text\n\n    def bright_cyan(self, text):\n        return text\n\n    def box(self, width, height, title=None):\n        return \"\"\n\n    def box_at(self, x, y, width, height, title=None):\n        return self\n\n    def capture(self):\n        return \"\".join(self._output)\n\n    def capture_lines(self):\n        return list(self._output)\n\n\nclass MockInput:\n    def __init__(self, keys=None):\n        self._keys = list(keys or [])\n        self._index = 0\n\n    def get_key(self):\n        if self._index < len(self._keys):\n            key = self._keys[self._index]\n            self._index += 1\n            return key\n        return None\n\n    def feed(self, key):\n        self._keys.append(key)\n\n    def remaining(self):\n        return len(self._keys) - self._index\n\n\ndef assert_screen(mock_renderer, *expected_lines):\n    lines = mock_renderer.capture_lines()\n    if lines != list(expected_lines):\n        import difflib\n        diff = \"\\n\".join(\n            difflib.ndiff(\n                [line + \"\\n\" for line in expected_lines],\n                [line + \"\\n\" for line in lines],\n            )\n        )\n        raise AssertionError(f\"Screen mismatch:\\n{diff}\")\n",
